verified_text:
#include <stdio.h>
int main() {
    printf("Printing even numbers from 1 to 10 (stopping if we hit 8):\n");
    for (int i = 1; i <= 10; i++) {
        if (i % 2 != 0) {
            continue;
        }
        if (i == 8) {
            printf("Reached 8! Breaking out of loop.\n");
            break;
        }
        printf("Number: %d\n", i);
    }
    return 0;
}

